// 20 named personas, one per archetype. Profiles, habits and ranges are assumptions under researcher review.
const PINFO={"The Provider": {"n": "Sipho Dlamini", "age": "32–52", "inc": "R9 000–R28 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "the app", "set": "township", "pr": "Mid-40s breadwinner on a steady salary, supporting a household of four or five. Money is planned around school fees, groceries and transport, and every rand has a job before the month starts.", "hab": "Gets paid on the 25th and spreads cash across accounts. Uses the app for balance checks and transfers, and prefers a branch for anything unusual. Keeps a payslip and a utility bill in a folder.", "pain": "Gets frustrated when asked for documents they handed over years ago. Has little time to finish a long form between work and home.", "help": "Reusing details the bank already holds. Clear steps and a way to save progress."}, "The Hustler": {"n": "Lindiwe Zulu", "age": "24–40", "inc": "R4 000–R16 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "the app", "set": "metro", "pr": "Late twenties, juggling two or three income streams a month. Income is real but lumpy, and nothing arrives with a payslip.", "hab": "Moves money constantly between wallets, cards and cash. Checks the app many times a day and sends payments from the phone. Keeps screenshots of proof of payment instead of formal records.", "pain": "Cannot prove income the way forms expect. Drops off when asked for payslips or employer details.", "help": "Letting bank statements or a simple self-declaration count as proof. Quick start, details later."}, "The First Salary Earner": {"n": "Thabo Nkosi", "age": "20–25", "inc": "R6 500–R14 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "the app", "set": "metro", "pr": "Just started a first job and needs an account for the salary. Quite possibly sending money home every month while learning how banking works.", "hab": "Compares apps and fees on social media. Opens the app straight away but is nervous about getting something wrong. Often relies on a parent or friend for advice.", "pain": "Worried about hidden fees and unfamiliar words. May not have a proof of address in their own name.", "help": "Plain language and fee clarity up front. Accepting an alternative to proof of address."}, "The Young Climber": {"n": "Naledi Khumalo", "age": "24–32", "inc": "R12 000–R28 000", "dev": "a high-end phone", "dat": "home wifi", "ch": "the app", "set": "metro", "pr": "Early-career professional on the way up, already banking digitally and looking for the next product as income grows.", "hab": "Does everything on the phone, expects biometrics and instant approval, and will abandon anything that feels slow. Compares products online before committing.", "pain": "Impatient with repeated forms and screens that feel like a branch process moved online.", "help": "Pre-filled details, biometric sign-in, and an upgrade path in a few taps."}, "The Informal Trader": {"n": "Mama Joyce Mahlangu", "age": "30–58", "inc": "R2 500–R9 000", "dev": "an entry-level phone", "dat": "small data bundles", "ch": "branch and ATM", "set": "township", "pr": "Runs a small cash business from home or a stall. Earns daily, saves in small amounts and keeps accounts of sales in her head or in a notebook.", "hab": "Mostly cash. Uses the phone for calls, WhatsApp and airtime, and is wary of spending data on large downloads. Learns a new process best when someone shows her.", "pain": "No payslip and no formal proof of address. Long forms and photo uploads cost data and are easy to get wrong.", "help": "A process that works on low data, with an agent or branch nearby when it goes wrong."}, "The Township Entrepreneur": {"n": "Bongani Sithole", "age": "28–50", "inc": "R5 000–R22 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "online banking", "set": "township", "pr": "Owns a small local business and employs two or three people. Takes in a lot of cash and card sales and keeps personal and business money mixed together.", "hab": "Pays suppliers in cash and by transfer, and uses the app to check that money arrived. Trusts people he knows and takes advice from other business owners.", "pain": "Income cannot be shown on a payslip. Gets stuck at income and business questions that do not fit his situation.", "help": "Business-friendly income questions and a human to help with documents."}, "The Community Builder": {"n": "Nomsa Cele", "age": "35–62", "inc": "R4 000–R14 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "online banking", "set": "township", "pr": "Holds a community together: runs the stokvel, helps neighbours with forms and is the person others ask about money.", "hab": "Handles other people's money, so she cares about trust and record-keeping. Uses WhatsApp heavily, and her phone is often a shared family device.", "pain": "Hesitates at declarations she does not fully understand, and worries about being responsible if something goes wrong.", "help": "Explanations in her home language and the option to ask someone before she signs."}, "The Grant Receiver": {"n": "Zanele Ngcobo", "age": "25–65", "inc": "R1 000–R2 800", "dev": "an entry-level phone", "dat": "small data bundles", "ch": "branch and ATM", "set": "township", "pr": "Receives a social grant as the main or only income, supporting several dependants. The account has to be simple, safe and free.", "hab": "Withdraws cash on grant day and spends it quickly. Uses a basic or older handset, runs out of data, and avoids anything that could lead to a charge.", "pain": "Photo capture and facial checks fail on older phones. No payslip and often no proof of address. A failed attempt can cost data and a trip to a branch.", "help": "Low-data steps that work on an entry-level phone, and a clear branch fallback."}, "The Pension Caregiver": {"n": "Mr Daniel Mokwena", "age": "58–75", "inc": "R3 500–R9 500", "dev": "an entry-level phone", "dat": "small data bundles", "ch": "branch and ATM", "set": "township", "pr": "Retired and living on a pension, with children and grandchildren depending on him. Cautious about change and about anything that might be a scam.", "hab": "Prefers branches and ATMs and visits on set days. Has a smartphone, often chosen by a relative, and uses it for calls and a few apps he has been taught.", "pain": "Small text, unfamiliar words and facial checks make him doubt whether the process is real.", "help": "Large text, human help available and reassurance that the process is safe."}, "The Saver": {"n": "Khanyi Radebe", "age": "28–55", "inc": "R8 000–R24 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "the app", "set": "township", "pr": "Disciplined and goal-driven, puts money aside every payday and tracks it. Looks for the account that protects savings from impulse spending.", "hab": "Reads the fee schedule before signing. Moves money to savings on payday and checks the app weekly. Dislikes products that nudge her to spend.", "pain": "Pushy upsells and unclear fees make her stop. Her time goes into reading the small print, so long terms slow her down.", "help": "Transparent fees and a clean path that does not push extras."}, "The Asset Aspirer": {"n": "Pieter van Wyk", "age": "28–45", "inc": "R14 000–R38 000", "dev": "a high-end phone", "dat": "home wifi", "ch": "the app", "set": "metro", "pr": "Saving for a deposit on a home or car. Looks at every product through the lens of how it affects a credit record and affordability.", "hab": "Tracks his credit score, compares offers and reads the terms. Applies when it is clear how the product helps with a goal.", "pain": "Drops off at affordability and decision steps if he does not see how they affect his future application.", "help": "Clear explanation of how the account helps his goal, and no surprises at the decision step."}, "The Security Seeker": {"n": "Gugu Mthembu", "age": "40–65", "inc": "R7 000–R22 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "branch and ATM", "set": "township", "pr": "Has been caught out by fraud or surprise fees and now checks everything twice. Trust is the product she is buying.", "hab": "Never clicks links in messages, always calls to confirm and keeps small balances in her transactional account. Reads every notification.", "pain": "Facial checks and permission requests look suspicious. Stops if the app asks for something she cannot explain.", "help": "Plain reasons for every permission and security prompt, and visible bank branding at each step."}, "The Commuter": {"n": "Vusi Msibi", "age": "22–45", "inc": "R6 000–R18 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "the app", "set": "metro", "pr": "Spends two or three hours a day on a taxi, train or bus. Does his banking in short windows during the commute.", "hab": "Uses the app on the move and expects each task to take minutes. Network drops in transit and sessions time out.", "pain": "Loses progress when the signal drops or the session expires, and has to start again.", "help": "Save and resume, and steps that survive a poor connection."}, "The Connected Customer": {"n": "Tshepiso Molefe", "age": "22–38", "inc": "R15 000–R45 000", "dev": "a high-end phone", "dat": "home wifi", "ch": "the app", "set": "metro", "pr": "Lives in the app. Uses several banking and fintech products and expects instant, seamless onboarding.", "hab": "Pays with the phone, uses digital wallets and keeps notifications tidy. Compares the speed of onboarding between providers.", "pain": "Any screen that asks for something the bank should already know feels broken.", "help": "Reusing stored identity and finishing in under two minutes."}, "The Side-Hustle Professional": {"n": "Kagiso Sebola", "age": "28–45", "inc": "R16 000–R40 000", "dev": "a high-end phone", "dat": "home wifi", "ch": "the app", "set": "metro", "pr": "Has a salary and a second income. Wants to keep the two apart and show both when applying for credit.", "hab": "Uses the app for both personal and business payments, tracks side income in a spreadsheet and sends invoices from the phone.", "pain": "Does not fit a single income question. Gets stuck declaring two sources of income.", "help": "Income questions that allow a salary and a side income."}, "The Single Parent": {"n": "Palesa Maseko", "age": "26–45", "inc": "R7 000–R20 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "the app", "set": "township", "pr": "Raising children on one income with very little spare time. Does her banking late in the evening once the children are asleep.", "hab": "Applies in short bursts and is interrupted often. Wants the account for school fees, groceries and an emergency buffer.", "pain": "Interrupted sessions and long forms. Time is the scarcest thing she has.", "help": "Short steps, save and resume, and no repeated questions."}, "The Emerging Professional": {"n": "Ayanda Naidoo", "age": "23–30", "inc": "R18 000–R45 000", "dev": "a high-end phone", "dat": "home wifi", "ch": "the app", "set": "metro", "pr": "Recent graduate with a growing salary and the first real chance to choose products. Expects fast, polished digital onboarding.", "hab": "Reads reviews, tries several banking apps and keeps whichever feels quickest. Switches easily if one is slow.", "pain": "Drops quickly at any friction. Verification delays and manual reviews are reasons to leave.", "help": "Instant verification and a clear visible progress indicator."}, "The Established Provider": {"n": "Johan Botha", "age": "38–58", "inc": "R30 000–R90 000", "dev": "a high-end phone", "dat": "home wifi", "ch": "the app", "set": "metro", "pr": "Senior earner with dependants and several accounts. Has little patience for retail-style flows and expects to be recognised as a client.", "hab": "Uses the app and online banking for transfers, and expects a relationship banker to help with anything complicated.", "pain": "Hates re-entering information and generic messaging. Large forms feel disrespectful of his time.", "help": "Recognition as an existing client, pre-filled forms and a fast path to a person."}, "The Digitally Curious": {"n": "Fatima Patel", "age": "25–55", "inc": "R8 000–R25 000", "dev": "a mid-range phone", "dat": "prepaid data", "ch": "the app", "set": "metro", "pr": "Exploring digital banking and wants to be sure about each step. Curious, open to change, and needs reassurance more than speed.", "hab": "Watches tutorial videos, asks friends and checks reviews. Stops if an unfamiliar word or screen appears.", "pain": "Unexplained terms and unexpected requests make her pause and leave to research.", "help": "Short explainers inside the flow and visible help."}, "The Financial Survivor": {"n": "Thandiwe Ndlovu", "age": "20–60", "inc": "R500–R4 000", "dev": "an entry-level phone", "dat": "small data bundles", "ch": "branch and ATM", "set": "township", "pr": "Lives day to day with very little cash. Income comes in small, irregular amounts and every fee matters.", "hab": "Spends money as soon as it arrives. Avoids anything with fees and keeps minimal balances. Data is bought in small bundles and used carefully.", "pain": "Cannot meet income or address checks, and avoids anything that looks like it will cost money.", "help": "A no-fee entry account with minimal documents, and an obvious human option."}};
// illustrated portraits supplied for the personas, keyed by archetype
const PIMG={"The Security Seeker": "data:image/jpeg;base64,", "The Pension Caregiver": "data:image/jpeg;base64,", "The Financial Survivor": "data:image/jpeg;base64,", "The Digitally Curious": "data:image/jpeg;base64,", "The Community Builder": "data:image/jpeg;base64,", "The Established Provider": "data:image/jpeg;base64,", "The Side-Hustle Professional": "data:image/jpeg;base64,", "The Single Parent": "data:image/jpeg;base64,", "The Commuter": "data:image/jpeg;base64,", "The Asset Aspirer": "data:image/jpeg;base64,"};
var XTRA_READY=false;
let CUSTSEL="";
const pinfo=n=>PINFO[n]||null,pname=n=>PINFO[n]?PINFO[n].n:n;
function pav(n,big){if(PIMG[n])return`<img class="av avimg${big?" big":""}" src="${PIMG[n]}" alt="Portrait of ${esc(pname(n))}">`;const nm=pname(n).replace(/^(Mr|Mrs|Ms|Mama)\s+/,""),w=nm.replace(/^The\s+/i,"").replace(/[^A-Za-z ]/g," ").trim().split(/\s+/),ini=((w[0]||"?")[0]+(w[1]?w[1][0]:"")).toUpperCase();let h=0;for(const c of String(n))h=(h*31+c.charCodeAt(0))>>>0;return`<span class="av${big?" big":""}" style="background:${AVC[h%AVC.length]}">${esc(ini)}</span>`}
function custRows(p,R){const n=R.cust.length;return p.personas.map((pe,j)=>{const q=R.perp[j].n-R.perp[j].inel;return{j,pe,n:R.perp[j].n,sh:R.perp[j].n/n*100,r:q>0?R.perp[j].opened/q*100:0}}).filter(x=>x.n>=20)}
const PFIX={select:"guide",details:"fields",idcap:"instant",verify:"instant",fica:"fica",decision:"decision",sign:"trust",none:"guide"};
function custSteps(p,j){return p.steps.map((s,k)=>({s,k,att:BASE.perp[j].att[k],r:BASE.perp[j].att[k]>0?BASE.perp[j].fail[k]/BASE.perp[j].att[k]:0,o:BASE.att[k]>0?BASE.fail[k]/BASE.att[k]:0})).filter(x=>x.att>0)}
const custPain=st=>st.filter(x=>!x.s.post&&x.s.tag!=="elig").sort((a,b)=>b.r-a.r);
const STYLEL={blunt:"Short and blunt",quiet:"Quiet, says little",chatty:"Chatty, wanders",complainer:"Complainer",easy:"Easy-going",suspicious:"Suspicious"},LMHW={L:"Low",M:"Medium",H:"High"};
function behChips(B){return`<h3 class="fh3">How they behave <span class="chip ass" style="margin-left:4px">ASSUMED</span></h3><div class="cuchips" style="margin-top:8px">
 <span>Usually ${B.mood.toLowerCase()}</span><span>Patience: ${LMHW[B.patience]}</span><span>Trust: ${LMHW[B.trust]}</span><span>Makes mistakes: ${LMHW[B.err]}</span><span>Gets distracted: ${LMHW[B.distract]}</span><span>${B.terms==="Reads"?"Reads the terms":B.terms==="Skims"?"Skims the terms":"Skips the terms"}</span><span>Comes back later: ${B.ret}%</span><span>When stuck: ${B.stuck}</span><span>Quits most at: ${(TAGLBL[B.quit]||B.quit).toLowerCase()}</span><span>Reading: ${B.reading.toLowerCase()}</span><span>English: ${B.english.toLowerCase()}</span></div>
 <div class="cuchips" style="margin-top:6px"><span>Talks: ${STYLEL[B.style]||B.style}</span><span>${B.polite==="H"?"Says things were fine, even when not":B.polite==="M"?"Fairly honest":"Says it straight"}</span><span>Up to ${B.maxW} words</span></div>`}
function drawCust(){
 const el=$("cuRoot");if(!el||!BASE)return;const p=cur(),rows=custRows(p,BASE).sort((a,b)=>a.r-b.r),ov=BASE.openN/Math.max(1,BASE.cust.length-BASE.perp.reduce((a,x)=>a+x.inel,0))*100;
 if(!rows.find(x=>x.pe.name===CUSTSEL))CUSTSEL=rows[0]?rows[0].pe.name:"";
 rows.forEach(x=>{x.st=custSteps(p,x.j);x.pain=custPain(x.st);x.rel=x.pain.slice().sort((a,b)=>(b.r-b.o)-(a.r-a.o));x.isRel=!!x.rel[0]&&x.rel[0].r-x.rel[0].o>=.01;x.hard=x.isRel?x.rel[0]:x.pain[0]});const sel=rows.find(x=>x.pe.name===CUSTSEL),mx=Math.max(...rows.map(x=>x.r),1),named=rows.some(x=>pinfo(x.pe.name));
 let h=`<div class="card"><h2>Meet the customers</h2><p class="lead">${named?"Synthetic customers walk this flow. Pick one to see it through their eyes.":"These are the customer groups behind this flow. Pick one to see where they struggle."}</p>
 <div class="ctlgrid" style="grid-template-columns:1fr"><div class="ctlbox"><div class="ctl-l">Read this first</div><div class="hint" style="margin:0">${p.personaSrc==="data"?"Differences between these groups come from your data.":"Who these people are and how they behave are <b>assumptions</b> being reviewed by research. "+(p.mock?"The funnel numbers for this account are mock data.":"The split between customers is not measured yet.")}</div></div></div>
 <div class="cugrid">${rows.map(x=>`<button class="cucard${x.pe.name===CUSTSEL?" on":""}" data-cu="${esc(x.pe.name)}">${pav(x.pe.name)}<span class="cu-t"><b>${esc(pname(x.pe.name))}</b><span>${pinfo(x.pe.name)?esc(x.pe.name):x.sh.toFixed(0)+"% of starters"}</span></span><span class="cu-r" style="color:${x.r<ov*.75?"var(--red)":"var(--ink)"}">${x.r.toFixed(0)}<i>in 100 open</i></span><span class="cu-b"><i style="width:${(x.r/mx*100).toFixed(0)}%"></i></span>${x.hard?`<span class="cu-h">${x.isRel?`Struggles most at <b>${esc(x.hard.s.name)}</b> · +${((x.hard.r-x.hard.o)*100).toFixed(0)} pts vs others`:`No screen harder than for others · most leave at <b>${esc(x.hard.s.name)}</b>`}</span>`:""}</button>`).join("")}</div></div>`;
 if(sel){const j=sel.j,I=pinfo(sel.pe.name),nj=BASE.perp[j].n,first=pname(sel.pe.name).replace(/^(Mr|Mrs|Ms|Mama)\s+/,"").split(" ")[0],who=I?first:"this group";
  const st=sel.st,worst=sel.hard,plist=[...sel.rel.filter(x=>x.r-x.o>=.01).slice(0,2),...sel.pain].filter((x,i,a)=>a.indexOf(x)===i).slice(0,3),rel=x=>x.r-x.o>.03?["Harder for "+who+" than for most","var(--red)"]:x.r-x.o<-.03?["Easier than for most, but still a big loss","var(--mut)"]:["About as hard as for everyone","var(--mut)"],
  pains=plist.map((x,i)=>{const rs=(x.s.reasons||REASON_BY_TAG[x.s.tag]||[]).slice(0,2).map(r=>r[0].toLowerCase()),idea=IDEAS.find(q=>q.k===PFIX[x.s.tag]),ok=idea&&affected(idea),rl=rel(x);
   return`<div class="frow"><div class="fnum">${i+1}</div><div class="fbody"><div class="ft">${esc(x.s.name)} <span class="chip">${esc(TAGLBL[x.s.tag]||"Other")}</span></div><div class="ff"><b style="color:var(--ink)">${(x.r*100).toFixed(0)} in 100</b> who reach it leave, against ${(x.o*100).toFixed(0)} for everyone. <span style="color:${rl[1]}">${esc(rl[0])}.</span></div>${rs.length?`<div class="ff">Likely reasons: ${esc(rs.join(", "))}.</div>`:""}${ok?`<div class="ffix">To test: “${esc(iTxt(idea).n)}” in Drop-off and ideas.</div>`:""}</div></div>`}).join(""),SR=softRuns(p).medium,q2=SR.perp[j].n-SR.perp[j].inel,rs=q2>0?SR.perp[j].opened/q2*100:0;
  h+=`<div class="card"><div class="cuhead">${pav(sel.pe.name,true)}<div><h2 style="margin:0">${esc(pname(sel.pe.name))}</h2><div class="fsub" style="margin-top:2px">${I?esc(sel.pe.name)+" · ":""}${sel.pe.seg==="existing"?"Already banks with us":"New to the bank"} · ${sel.sh.toFixed(0)}% of people who start</div></div></div>
  ${I?`<p class="cuprof">${esc(I.pr)}</p>${typeof packChips==="function"&&PACKBY&&PACKBY[sel.pe.name]&&PSTAT?packChips(sel.pe.name):`<div class="cuchips"><span>Age ${I.age}</span><span>${I.inc} a month</span><span>Mostly ${I.set}</span><span>Uses ${I.dev}</span><span>${I.dat[0].toUpperCase()+I.dat.slice(1)}</span><span>Prefers ${I.ch}</span></div>`}`:(sel.pe.note?`<p class="cuprof">${esc(sel.pe.note)}</p>`:"")}${typeof packGroup==="function"?packGroup(sel.pe.name):""}
  <div class="fpill" style="grid-template-columns:repeat(3,1fr)"><div class="fp"><div class="fp-n">Opens an account today</div><div class="fp-s">${sel.r.toFixed(0)} <small>in 100</small></div><div class="fp-q">Against ${ov.toFixed(0)} in 100 for everyone</div></div>
  <div class="fp"><div class="fp-n">${sel.isRel?"Where "+esc(who)+" struggles most":"Where most are lost"}</div><div class="fp-s" style="font-size:20px;line-height:1.5">${esc(worst.s.name)}</div><div class="fp-q">${(worst.r*100).toFixed(0)} in 100 who reach it leave, against ${(worst.o*100).toFixed(0)} overall</div></div>
  ${p.standalone?`<div class="fp"><div class="fp-n">Share of people who start</div><div class="fp-s">${sel.sh.toFixed(0)}<small>%</small></div><div class="fp-q">A general mix of customers. Change it under Drop-off and ideas.</div></div>`:`  <div class="fp"><div class="fp-n">With the Soft Banking Profile</div><div class="fp-s" style="color:var(--blue)">${rs.toFixed(0)} <small>in 100</small></div><div class="fp-q">${rs>=sel.r?"+":"−"}${Math.abs(rs-sel.r).toFixed(0)} against today. Effect size is an assumption.</div></div>`}</div>
  ${BTRAIT[sel.pe.name]?behChips(BTRAIT[sel.pe.name]):""}
  ${I?`<div class="cutwo"><div><h3 class="fh3">Habits</h3><p>${esc(I.hab)}</p></div><div><h3 class="fh3">What gets in the way</h3><p>${esc(I.pain)}</p><h3 class="fh3">What would help</h3><p>${esc(I.help)}</p></div></div>`:""}
  <h3 class="fh3">Pain points for ${esc(who)}</h3><div class="hint" style="margin:6px 0 0">Where ${esc(who)} struggles more than other customers comes first, then where most are lost. Reasons are typical for that type of screen, not observed.</div>${pains}
  <h3 class="fh3">Walking the flow as ${esc(who)}</h3><div class="hint" style="margin:6px 0 4px">Share who leave at each screen. Yellow marks the pain points listed above. The dark tick is everyone else.</div>
  ${st.map((x,i)=>{const pi=plist.indexOf(x),amb='style="background:var(--amber);border-color:var(--amber);color:#fff"';return`<div class="fscr"><div class="fscr-n"><span class="fidx">${i+1}</span>${esc(x.s.name)}${pi===0?` <span class="chip" ${amb}>HARDEST</span>`:pi>0?` <span class="chip" ${amb}>PAIN POINT</span>`:""}</div><div class="fscr-b" style="position:relative;overflow:visible"><i style="width:${Math.max(x.r*100,1).toFixed(0)}%;background:${pi>=0?"var(--amber)":"var(--blue)"}"></i><u style="left:${(x.o*100).toFixed(0)}%"></u></div><div class="fscr-v">${(x.r*100).toFixed(0)}%</div></div>`}).join("")}</div>`}
 el.innerHTML=h;goalSwap(el);
}
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest("[data-cu]");if(b){CUSTSEL=b.dataset.cu;drawCust();const c=$("cuRoot").querySelectorAll(".card")[1];if(c&&c.scrollIntoView)c.scrollIntoView({behavior:"smooth",block:"start"})}});
